# Editable Word example. The first page is a copy-ready blue methods box.
args<-commandArgs(FALSE);script<-sub('^--file=','',args[grepl('^--file=',args)][1])
setwd(normalizePath(file.path(dirname(script),'..'),mustWork=TRUE))
suppressPackageStartupMessages(library(officer))
source('R/model.R');a<-default_assumptions()
stopifnot(a$education_income_elasticity==.5,a$health_income_elasticity==.8,
 a$service_cost_set=='current',a$health_pressure_source=='assumed',a$macro_mode=='prices')
out<-'documentation/fiscal_projection_methods_box.docx'
blue<-'153F63';pale<-'EAF2F8';ink<-'183449'
doc<-read_docx()
doc<-body_set_default_section(doc,prop_section(
 page_size=page_size(width=8.2677,height=11.6929),
 page_margins=page_mar(top=.65,bottom=.65,left=.72,right=.72)))
doc<-docx_set_paragraph_style(doc,style_id='e61Body',style_name='e61 body',
 fp_t=fp_text(font.family='Arial',font.size=9.2,color=paste0('#',ink)),
 fp_p=fp_par(padding.bottom=4,line_spacing=1.05))
body_add_par<-function(x,value)officer::body_add_par(x,value,style='e61 body')
doc<-body_add_fpar(doc,fpar(ftext('Fiscal projections',fp_text(font.family='Arial',font.size=19,bold=TRUE,color=paste0('#',blue)))))
doc<-body_add_fpar(doc,fpar(ftext('Example report box | Reference settings at 18 November 2026',
 fp_text(font.family='Arial',font.size=9,color='#586B7C'))))
paragraphs<-list(
 c('Scope and starting point. ',paste0('The e61 fiscal model projects consolidated Australian general-government spending, revenue and debt from 2029-30 to 2065-66. Transfers between governments are consolidated. The 2029-30 fiscal totals and debt stocks are anchored to the PBO National Fiscal Outlook. ABS Government Finance Statistics (GFS) provide 2024-25 spending and revenue composition; programme allocations are projected to 2030 and reconciled to the PBO totals. These allocations are e61 estimates, not PBO programme forecasts. [1, 2]')),
 c('Spending method. ',paste0('Each spending category combines demographic demand, coverage, input costs, service intensity and policy settings. Annual IGR age/sex population projections drive age composition; changing total population growth scales all age/sex cells equally. Fixed IGR age-cost profiles proxy health and aged-care demand; education uses age-band populations with fixed participation. AIHW funding data allocate health sub-functions within the ABS total, so these are not IGR programme categories. NDIA participation and age-specific budget/utilisation data inform NDIS demand, with an assumed retention rule for older cohorts. [3-5]')),
 c('Costs and service standards. ',paste0('Real wages follow economy-wide productivity. Health and education resource-cost baskets combine labour and non-labour inputs; observed cost shares are used where available, with proxies elsewhere. Non-labour inputs follow domestic prices; capital costs are not separately projected. Service efficiency defaults to 25% of economy-wide productivity growth in applicable baskets, rather than in transfers, medicines or the VET funding-index rule. Additional income-related service intensity has elasticity 0.8 for health and 0.5 for education with respect to real GDP per person. Health uses an internationally informed scenario coefficient; education 0.5 is an unverified assumption. Both act beyond explicit input costs. [6, 7]')),
 c('Reference assumptions. ',sprintf('Annual labour productivity grows %.1f%%, domestic prices %.1f%% and population %.1f%%; average hours and the terms of trade are constant. Nominal GDP is implied by output, prices and terms of trade. IGR aggregate participation paths shape employment. Remaining health spending pressure defaults to zero; education also defaults to zero additional annual growth. Efficiency and additional growth are unestimated assumptions; review overlap with income-related intensity. [3]',100*a$productivity,100*a$domestic_price_growth,100*a$population_growth)),
 c('Revenue and debt. ',sprintf('Personal income tax applies tax schedules to ATO income-percentile cells, with wage-indexed thresholds by default. Other receipts follow structural tax-base proxies; company tax is a calibrated GDP share linked to terms of trade. Age Pension receipt reflects public-data cohort wealth and means tests. The reference assumes %.1f%% real superannuation returns and a nominal borrowing rate converging to %.1f%% by 2040. Interest is paid on gross debt; financial assets earn interest. Deficits and net investment feed debt accumulation; no automatic tax increase or spending cut stabilises debt. [1, 2, 8]',100*a$super_real_return,100*a$interest_rate)),
 c('Interpretation. ',paste0('These are conditional scenarios, not validated forecasts. Published data supply levels and profiles; e61 calibration, proxies and unverified assumptions supply the remaining structure. Reported scenarios must state departures from these reference settings. Real per-person spending uses 2030 prices and total residents; decomposition bars allocate interactions across drivers using Shapley accounting and do not identify causal effects.'))
)
esc<-function(s){s<-gsub('&','&amp;',s,fixed=TRUE);s<-gsub('<','&lt;',s,fixed=TRUE);gsub('>','&gt;',s,fixed=TRUE)}
run<-function(text,bold=FALSE,color=ink,size=20)paste0('<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/>',
 if(bold)'<w:b/>' else '', '<w:color w:val="',color,'"/><w:sz w:val="',size,'"/></w:rPr><w:t xml:space="preserve">',esc(text),'</w:t></w:r>')
para<-function(v)paste0('<w:p><w:pPr><w:spacing w:after="110" w:line="246" w:lineRule="auto"/></w:pPr>',run(v[1],TRUE),run(v[2]),'</w:p>')
cell<-function(content,fill)paste0('<w:tc><w:tcPr><w:tcW w:w="9820" w:type="dxa"/><w:shd w:val="clear" w:fill="',fill,'"/><w:tcMar><w:top w:w="160" w:type="dxa"/><w:left w:w="200" w:type="dxa"/><w:bottom w:w="160" w:type="dxa"/><w:right w:w="200" w:type="dxa"/></w:tcMar></w:tcPr>',content,'</w:tc>')
xml<-paste0('<w:tbl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:tblPr><w:tblW w:w="9820" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:tblBorders><w:top w:val="single" w:sz="6" w:color="153F63"/><w:left w:val="single" w:sz="6" w:color="153F63"/><w:bottom w:val="single" w:sz="6" w:color="153F63"/><w:right w:val="single" w:sz="6" w:color="153F63"/></w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="9820"/></w:tblGrid>',
 '<w:tr><w:trPr><w:cantSplit/></w:trPr>',cell(paste0('<w:p><w:pPr><w:keepNext/><w:spacing w:after="0"/></w:pPr>',run('Box 1. How the fiscal projections are constructed',TRUE,'FFFFFF',24),'</w:p>'),blue),'</w:tr>',
 '<w:tr><w:trPr><w:cantSplit/></w:trPr>',cell(paste(vapply(paragraphs,para,character(1)),collapse=''),pale),'</w:tr></w:tbl>')
doc<-body_add_xml(doc,xml)
doc<-body_add_break(doc)
doc<-body_add_fpar(doc,fpar(ftext('Sources and evidence notes',fp_text(font.family='Arial',font.size=16,bold=TRUE,color=paste0('#',blue)))))
doc<-body_add_par(doc,'The numbered references support the inputs or methods identified in the box. They do not endorse the complete e61 model or its parameter choices. Links refer to the data vintages used, rather than implying that every source is the latest release.')
source_note<-function(doc,number,title,note,links){
 doc<-body_add_fpar(doc,fpar(ftext(paste0('[',number,'] ',title),fp_text(font.family='Arial',font.size=10,bold=TRUE,color=paste0('#',blue))),fp_p=fp_par(padding.top=4,padding.bottom=2)))
 doc<-body_add_par(doc,note)
 chunks<-lapply(seq_along(links),function(i)hyperlink_ftext(paste0(if(i>1)' | ' else '',names(links)[i]),
   prop=fp_text(font.family='Arial',font.size=9,color='#17669C',underlined=TRUE),href=links[[i]]))
 body_add_fpar(doc,do.call(fpar,c(chunks,list(fp_p=fp_par(padding.bottom=4)))))
}
doc<-source_note(doc,1,'PBO: fiscal anchor','2026-27 National Fiscal Outlook, Tables 1-2: consolidated starting totals and debt. Subsequent sector allocations and long-run paths are e61 calculations.',c('PBO National Fiscal Outlook'='https://www.pbo.gov.au/publications-and-data/publications/2026-27-National-Fiscal-Outlook'))
doc<-source_note(doc,2,'ABS: observed fiscal composition','Government Finance Statistics and Taxation Revenue 2024-25. COFOG-A functional totals control spending; GFS education Table 095 supplies school, tertiary and other totals. e61 bridges these observations to 2030.',c('Government Finance Statistics'='https://www.abs.gov.au/statistics/economy/government/government-finance-statistics-annual/2024-25','Taxation Revenue'='https://www.abs.gov.au/statistics/economy/government/taxation-revenue-australia/2024-25'))
doc<-source_note(doc,3,'Treasury and Centre for Population: demographic and labour paths','2026 IGR annual age/sex population projections; IGR health and aged-care age-cost profiles and sex-specific aggregate participation paths. Applying Commonwealth age-cost profiles to consolidated services is a proxy; education age bands do not model enrolment choices.',c('2026 IGR'='https://treasury.gov.au/publication/2026-intergenerational-report','Annual population projections'='https://population.gov.au/data-and-forecasts/projections'))
doc<-source_note(doc,4,'AIHW: health allocation','Health Expenditure Australia 2024-25 government funding by service area. Named Commonwealth and state-funded blocks are reconciled to the ABS health total. Other health includes research, other services and accounting/classification differences.',c('AIHW government funding'='https://www.aihw.gov.au/reports/health-welfare-expenditure/health-expenditure-australia-2024-25/contents/spending-trends-by-source/australian-government-spending'))
doc<-source_note(doc,5,'NDIA: participant and age-cost profiles','June 2025 participation, plan-budget and utilisation data. Budget times lagged utilisation is a relative cost proxy, not observed annual payments per person. Within-age cost weights are held fixed; retained older cohorts use a population-based retention proxy.',c('NDIA participant datasets'='https://dataresearch.ndis.gov.au/datasets/participant-datasets'))
doc<-source_note(doc,6,'Sector evidence: labour and funding weights','IHACPA hospital costs, ACARA school expenditure, university finance data and the National Skills Agreement inform input/funding weights. These are scope proxies, not estimates of long-run efficiency. The university/VET allocation uses cross-source expense weights.',c('IHACPA 2023-24'='https://www.ihacpa.gov.au/resources/national-hospital-cost-data-collection-public-sector-2023-24','ACARA 2024, Table 9.3'='https://dataandreporting.blob.core.windows.net/anrdataportal/ANR-Documents/ANR2024/nationalreportonschoolinginaustralia_2024_Chapter9.pdf','University finance 2024'='https://www.education.gov.au/higher-education-publications/finance-publication','National Skills Agreement'='https://federalfinancialrelations.gov.au/sites/federalfinancialrelations.gov.au/files/2023-12/national-skills-agreement.pdf'))
doc<-source_note(doc,7,'OECD: health projection framework','Fiscal Sustainability of Health Systems, long-term projections chapter, informs the income/cost/demography approach. Health elasticity 0.8 is an internationally informed scenario choice, not an Australian causal estimate. Education 0.5, efficiency at 25% and remaining-growth assumptions are unverified e61 assumptions.',c('OECD health projections methodology'='https://www.oecd.org/en/publications/fiscal-sustainability-of-health-systems_880f3195-en/full-report/component-6.html'))
doc<-source_note(doc,8,'ATO, DSS and ABS: revenue and pension inputs','ATO Taxation Statistics 2023-24 income cells; DSS June 2026 pension receipt; ABS SIH 2019-20 wealth; published means-test rules. Joint wealth distributions, retirement transitions and drawdown are provisional e61 proxies requiring future HILDA estimation. The 4% return and 4.4% terminal borrowing rate are scenario assumptions.',c('ATO Taxation Statistics 2023-24'='https://data.gov.au/data/dataset/taxation-statistics-2023-24','DSS pension demographics'='https://data.gov.au/data/dataset/dss-payment-demographic-data','ABS household wealth'='https://www.abs.gov.au/statistics/economy/finance/household-income-and-wealth-australia/2019-20'))
doc<-body_add_fpar(doc,fpar(ftext('Using this box in a report',fp_text(font.family='Arial',font.size=10,bold=TRUE,color=paste0('#',blue)))))
doc<-body_add_par(doc,'Copy the entire blue table into the report to retain its shading. The wording describes current reference defaults, not every user scenario. For each reported figure, state departures using the downloaded assumption_* fields and retain the evidence-register CSV. Default zero debt-interest feedback and no fixed spending/GDP overrides are assumed here. Per-person decompositions describe direct model arithmetic, not an economy-wide no-ageing counterfactual.')
print(doc,target=out)
text<-docx_summary(read_docx(out))$text
stopifnot(any(grepl('unverified assumption',text,fixed=TRUE)),any(grepl('Box 1.',text,fixed=TRUE)))
writeLines(vapply(paragraphs,function(v)paste(v,collapse=''),character(1)),
 'outputs/fiscal_projection_methods_box_text.txt',useBytes=TRUE)
cat('Created ',normalizePath(out,winslash='/'),'\n',sep='')
